//
//  HopSplashView.swift
//  HopChat-1
//
//  The animated continuation of the (plain navy) launch screen: the lava
//  fades in while the mark is drawn like a pen stroke — from the top, round
//  the bubble, into the tail and up the trail — and the message ball pops out
//  of the end of the trail into its place.
//
//  The drawing reveals the real, variable-width mark through a mask: a wide
//  round-capped stroke along the mark's centreline, trimmed to the progress.
//  Geometry comes from HopMarkGeometry (generated by design/logo/hopmark.py).
//

import SwiftUI

struct HopSplashView: View {

    /// Called once the ball has landed (immediately under Reduce Motion).
    var onFinished: () -> Void = {}

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var showLava = false
    @State private var drawn: CGFloat = 0
    @State private var showTip = false
    @State private var ballOut = false
    @State private var pulse = false

    static let markSize: CGFloat = 140
    private static let drawDuration = 1.05

    private var unit: CGFloat { Self.markSize / HopMarkGeometry.canvas }
    private var ballDiameter: CGFloat { HopMarkGeometry.ballRadius * 2 * unit }

    var body: some View {
        ZStack {
            Color("LaunchBackground")

            LavaBackground()
                .environment(\.colorScheme, .dark)
                .opacity(showLava ? 1 : 0)

            ZStack(alignment: .topLeading) {
                Image("HopMarkStroke")
                    .resizable()
                    .renderingMode(.template)
                    .foregroundStyle(.white)
                    .mask {
                        HopPenPath()
                            .trim(from: 0, to: drawn)
                            .stroke(style: StrokeStyle(lineWidth: (HopMarkGeometry.maxStrokeWidth + 24) * unit,
                                                       lineCap: .round, lineJoin: .round))
                    }
                    .shadow(color: Color(red: 0.45, green: 0.5, blue: 1).opacity(0.8), radius: 10)

                // Glowing pen tip riding the front of the stroke.
                HopPenTip(progress: drawn, radius: 5)
                    .fill(.white)
                    .shadow(color: Color(red: 0.6, green: 0.7, blue: 1), radius: 8)
                    .shadow(color: Color(red: 0.45, green: 0.5, blue: 1), radius: 16)
                    .opacity(showTip ? 1 : 0)

                ball
            }
            .frame(width: Self.markSize, height: Self.markSize)
        }
        .ignoresSafeArea()
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(Text("Starting HopChat…"))
        .task { await run() }
    }

    // MARK: Ball

    /// Pops out of the trail's end and springs up into its resting place.
    private var ball: some View {
        let center = ballOut ? HopMarkGeometry.ballCenter : HopMarkGeometry.trailEnd
        return Circle()
            .fill(RadialGradient(colors: [.white, Color(red: 1, green: 0.75, blue: 0.95)],
                                 center: .center, startRadius: 0, endRadius: ballDiameter / 2))
            .frame(width: ballDiameter, height: ballDiameter)
            .shadow(color: Color(red: 1, green: 0.35, blue: 0.85).opacity(pulse ? 0.95 : 0.6),
                    radius: pulse ? 14 : 8)
            .scaleEffect(ballOut ? 1 : 0.1)
            .opacity(ballOut ? 1 : 0)
            .offset(x: center.x * unit - ballDiameter / 2,
                    y: center.y * unit - ballDiameter / 2)
    }

    // MARK: Sequence

    private func run() async {
        if reduceMotion {
            showLava = true
            drawn = 1
            ballOut = true
            onFinished()
            return
        }
        withAnimation(.easeOut(duration: 0.7)) { showLava = true }
        try? await Task.sleep(for: .milliseconds(120))

        showTip = true
        withAnimation(.timingCurve(0.45, 0.05, 0.25, 1, duration: Self.drawDuration)) { drawn = 1 }
        try? await Task.sleep(for: .seconds(Self.drawDuration - 0.05))

        withAnimation(.easeOut(duration: 0.2)) { showTip = false }
        withAnimation(.spring(response: 0.38, dampingFraction: 0.55)) { ballOut = true }
        UIImpactFeedbackGenerator(style: .soft).impactOccurred()
        try? await Task.sleep(for: .milliseconds(250))
        withAnimation(.easeInOut(duration: 0.9).repeatForever(autoreverses: true)) { pulse = true }
        try? await Task.sleep(for: .milliseconds(300))
        onFinished()
    }
}

// MARK: - Pen path

/// The mark's centreline, scaled from the 1024 canvas into the view.
struct HopPenPath: Shape {
    func path(in rect: CGRect) -> Path {
        let k = min(rect.width, rect.height) / HopMarkGeometry.canvas
        var path = Path()
        path.addLines(HopMarkGeometry.centerline.map { CGPoint(x: rect.minX + $0.x * k, y: rect.minY + $0.y * k) })
        return path
    }
}

/// A dot at `progress` along the pen path (animatable, so it follows `trim`).
private struct HopPenTip: Shape {
    var progress: CGFloat
    var radius: CGFloat

    var animatableData: CGFloat {
        get { progress }
        set { progress = newValue }
    }

    func path(in rect: CGRect) -> Path {
        guard progress > 0.001, progress < 0.999 else { return Path() }
        let k = min(rect.width, rect.height) / HopMarkGeometry.canvas
        let p = PenPathLength.point(at: progress)
        let c = CGPoint(x: rect.minX + p.x * k, y: rect.minY + p.y * k)
        return Path(ellipseIn: CGRect(x: c.x - radius, y: c.y - radius, width: radius * 2, height: radius * 2))
    }
}

/// Arc-length lookup so the tip moves exactly as `trim` reveals the stroke.
private enum PenPathLength {
    static let points = HopMarkGeometry.centerline
    static let cumulative: [CGFloat] = {
        var out: [CGFloat] = [0]
        for i in 1..<points.count {
            out.append(out[i - 1] + hypot(points[i].x - points[i - 1].x, points[i].y - points[i - 1].y))
        }
        return out
    }()

    static func point(at progress: CGFloat) -> CGPoint {
        let target = progress * (cumulative.last ?? 0)
        var lo = 0
        var hi = cumulative.count - 1
        while hi - lo > 1 {
            let mid = (lo + hi) / 2
            if cumulative[mid] < target { lo = mid } else { hi = mid }
        }
        let span = cumulative[hi] - cumulative[lo]
        let t = span > 0 ? (target - cumulative[lo]) / span : 0
        return CGPoint(x: points[lo].x + (points[hi].x - points[lo].x) * t,
                       y: points[lo].y + (points[hi].y - points[lo].y) * t)
    }
}

